    "titleEn": "Recording Voice-Overs for Presentations and Tutorials on Your Phone: A Budget Setup for Clear Sound",
    "metaTitleEn": "Record Clear Voice-Overs on Your Phone",
    "metaDescriptionEn": "How to record narration for lectures, tutorials, and educational content with just a phone: room setup, script writing, speaking technique, and EQ clean-up.",
